(()=>{const variants=[["Portal", "孔洞门户", "中心大洞与卫星小洞", "不规则多孔陨石的中心洞口形成主循环，附近小洞形成局部回流。"], ["Oblique", "斜向裂隙", "倾斜长洞", "液态银沿倾斜裂隙的内壁回转，保持岩石外缘稳定。"], ["Twin Core", "双洞循环", "上下双环", "两个洞口各自环流，在中间腰部产生视觉连接。"], ["Rift", "横向洞穴", "横向宽洞", "金属沿横向洞口的长弧循环，突出厚重岩石和流动银面的反差。"], ["Relic", "异星遗迹", "圆洞与尖角", "圆洞中的液态金属循环流转，外围保留不对称遗迹轮廓。"]];let active=1,paused=false;const host=document.querySelector('#poster-host'),templates=[...document.querySelectorAll('.study-preview .acid-poster')].map(p=>p.outerHTML);function choose(mode,scroll){active=mode;host.querySelector('.acid-poster')?.acidPoster?.destroy();host.innerHTML=templates[mode-1].replace('acid-mini','').replace('tabindex="-1"','tabindex="0"');new AcidPoster(host.firstElementChild,{paused});const v=variants[mode-1];document.querySelector('#active-number').textContent='R0'+mode+' / '+v[0].toUpperCase();document.querySelector('#active-title').textContent=v[1];document.querySelector('#active-description').textContent=v[3];document.querySelector('#choose-motion').textContent='暂选 A0'+mode+' ↗';document.querySelectorAll('button[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.mode)===mode)));if(scroll)document.querySelector('#live-study').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'})}document.querySelectorAll('button[data-mode]').forEach(b=>b.addEventListener('click',()=>choose(Number(b.dataset.mode),true)));document.querySelector('#pause-motion').addEventListener('click',e=>{paused=!paused;document.querySelectorAll('.acid-poster').forEach(p=>p.acidPoster?.setPaused(paused));e.currentTarget.setAttribute('aria-pressed',String(paused));e.currentTarget.textContent=paused?'播放动态 ▷':'暂停动态 Ⅱ'});document.querySelector('#choose-motion').addEventListener('click',()=>{document.querySelector('#choice-message').textContent='已暂选 A0'+active+' '+variants[active-1][1]+'。请在聊天中确认编号，再替换到正式主页。';try{localStorage.setItem('chao-meteor-choice',String(active))}catch{}});})();